4	import { Separator } from "@/components/ui/separator";
5	import { Sheet, SheetContent } from "@/components/ui/sheet";
6	import { ScrollArea } from "@/components/ui/scroll-area";
7	import { Phone, Mail, FileText, Archive, MapPin, Download, X, Linkedin, Calendar, UserX, MessageCircle } from "lucide-react";
8	import { toast } from "sonner";
9	import type { Result } from "@/pages/Index";
10	import type { HiringStage } from "@/hooks/useStageTracker";
11	
12	import CandidateSummary from "@/components/candidate/CandidateSummary";
13	import CandidateSummaryCard from "@/components/candidate/CandidateSummaryCard";
14	import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
15	import ExperiencePanel from "@/components/candidate/ExperiencePanel";
16	import EducationPanel from "@/components/candidate/EducationPanel";
17	import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
18	import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
19	import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
20	import StageTracker from "@/components/candidate/StageTracker";
21	import ScorecardPanel from "@/components/candidate/ScorecardPanel";
22	import ScorecardSummary from "@/components/candidate/ScorecardSummary";
23	import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
24	import CandidateNotesPanel from "@/components/candidate/CandidateNotesPanel";
25	import InterviewsPanel from "@/components/candidate/InterviewsPanel";
26	import ScheduleInterviewDialog from "@/components/ScheduleInterviewDialog";
27	import RejectCandidateDialog from "@/components/candidate/RejectCandidateDialog";
28	import WhatsAppOutreachDialog from "@/components/candidate/WhatsAppOutreachDialog";
29	import CandidateTagInput from "@/components/candidate/CandidateTagInput";
30	import AssigneeSelector from "@/components/candidate/AssigneeSelector";
31	import AuthenticityReport from "@/components/candidate/AuthenticityReport";
32	import AddToPoolButton from "@/components/candidate/AddToPoolButton";
33	import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
34	import { extractLinkedInUrl } from "@/lib/linkedin";
35	import type { CandidateTag } from "@/hooks/useCandidateTags";
36	import type { TeamMember } from "@/hooks/useTeam";
37	
38	interface CandidateDetailSheetProps {
39	  result: Result | null;
40	  isOpen: boolean;
41	  onClose: () => void;
42	  jobId?: string | null;
43	  jobTitle?: string | null;
44	  teamId?: string | null;
45	  formatCandidateName: (filename: string) => string;
46	  onDownload: (filePath: string, filename: string) => void;
47	  onDismiss: (resumeId: string) => void;
48	  currentStage?: HiringStage | null;
49	  stageUpdatedAt?: string | null;
50	  onStageChange?: (resumeId: string, stage: HiringStage) => void;
51	  tags?: CandidateTag[];
52	  teamMembers?: TeamMember[];
53	  onAddTag?: (params: { resumeId: string; tag: string; color?: string }) => void;
54	  onRemoveTag?: (tagId: string) => void;
55	  onAssigned?: (resumeId: string, userId: string | null) => void;
56	  blindMode?: boolean;
57	}
