59	const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
60	  if (score >= 70) return { label: "Strong", variant: "success" };
61	  if (score >= 40) return { label: "Good", variant: "warning" };
62	  return { label: "Weak", variant: "destructive" };
63	};
64	
65	const CandidateDetailSheet = ({
66	  result: r,
67	  isOpen,
68	  onClose,
69	  jobId,
70	  jobTitle,
71	  teamId,
72	  formatCandidateName,
73	  onDownload,
74	  onDismiss,
75	  currentStage,
76	  stageUpdatedAt,
77	  onStageChange,
78	  tags = [],
79	  teamMembers = [],
80	  onAddTag,
81	  onRemoveTag,
82	  onAssigned,
83	  blindMode = false,
84	}: CandidateDetailSheetProps) => {
85	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
86	  const [scheduleOpen, setScheduleOpen] = useState(false);
87	  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
88	  const [whatsappOpen, setWhatsappOpen] = useState(false);
89	
90	  if (!r) return null;
91	
92	  const strength = getStrengthLabel(r.overall_score);
93	  const linkedinUrl = extractLinkedInUrl(r);
94	  const candidateName = r.candidate_name || formatCandidateName(r.filename);
95	
96	  return (
97	    <>
98	      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
99	        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col gap-0 [&>button]:hidden">
100	          {/* Dark hero header */}
101	          <div className="bg-foreground text-background px-6 pt-6 pb-5 shrink-0 relative">
102	            <button onClick={onClose} className="absolute top-4 right-4 rounded-sm opacity-70 hover:opacity-100 transition-opacity">
103	              <X className="h-4 w-4" />
104	            </button>
105	
106	            <div className="space-y-3">
107	              <div>
108	                <h2 className="text-xl font-semibold truncate pr-8">
109	                  {blindMode ? `Candidate` : candidateName}
110	                </h2>
111	                <div className="flex items-center gap-2 mt-1 flex-wrap text-background/60">
112	                  {r.candidate_location && (
113	                    <span className="flex items-center gap-1 text-xs">
114	                      <MapPin className="h-3 w-3" /> {r.candidate_location}
115	                    </span>
116	                  )}
117	                  {r.candidate_email && <span className="text-xs">{r.candidate_email}</span>}
118	                </div>
119	              </div>
120	
121	              {/* Score + badge row */}
122	              <div className="flex items-end gap-4">
123	                <div>
124	                  <span className="text-xs text-background/50 block">Overall Match</span>
125	                  <span className="text-4xl font-bold tabular-nums">{r.overall_score?.toFixed(0)}%</span>
126	                </div>
127	                <div className="flex items-center gap-2 pb-1.5">
128	                  <Badge variant={strength.variant} className="shadow-sm">{strength.label}</Badge>
129	                  {r.scoring_version === "heuristic" && <Badge variant="secondary">Quick</Badge>}
130	                  {r.confidence ? <Badge variant="outline" className="text-background/70 border-background/20">{r.confidence}% confidence</Badge> : null}
131	                </div>
132	              </div>
133	
134	              {/* Progress bar */}
135	              <div className="h-1.5 rounded-full bg-background/20 overflow-hidden">
136	                <div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${Math.min(r.overall_score, 100)}%` }} />
137	              </div>
138	            </div>
139	          </div>
140	
141	          {/* Action buttons */}
142	          <div className="px-6 py-3 flex items-center gap-2 border-b border-border shrink-0 bg-muted/30">
143	            {r.candidate_phone && (
144	              <>
145	                <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
146	                  onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
147	                  <Phone className="h-3 w-3" /> Call
148	                </Button>
149	                <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs border-[#25D366]/30 text-[#25D366] hover:bg-[#25D366]/10"
150	                  onClick={() => setWhatsappOpen(true)}>
151	                  <MessageCircle className="h-3 w-3" /> WhatsApp
152	                </Button>
153	              </>
154	            )}
155	            {r.candidate_email && (
156	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
157	                onClick={() => setEmailDialogOpen(true)}>
158	                <Mail className="h-3 w-3" /> Email
159	              </Button>
160	            )}
161	            {jobId && (
162	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
163	                onClick={() => setScheduleOpen(true)}>
164	                <Calendar className="h-3 w-3" /> Schedule
165	              </Button>
166	            )}
167	            {r.file_path && (
168	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
169	                onClick={() => onDownload(r.file_path!, r.filename)}>
170	                <Download className="h-3 w-3" /> Resume
171	              </Button>
172	            )}
173	            {linkedinUrl && (
174	              <TooltipProvider>
175	                <Tooltip>
176	                  <TooltipTrigger asChild>
177	                    <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs border-[#0A66C2]/30 text-[#0A66C2] hover:bg-[#0A66C2]/10"
178	                      onClick={() => window.open(linkedinUrl, "_blank", "noopener,noreferrer")}>
179	                      <Linkedin className="h-3 w-3" /> LinkedIn
180	                    </Button>
181	                  </TooltipTrigger>
182	                  <TooltipContent>View LinkedIn Profile</TooltipContent>
183	                </Tooltip>
184	              </TooltipProvider>
185	            )}
186	            <div className="ml-auto flex items-center gap-1">
187	              {jobId && teamId && (
188	                <AddToPoolButton
189	                  resumeId={r.resume_id}
190	                  jobId={jobId}
191	                  teamId={teamId}
192	                  isInPool={(r as any).in_talent_pool ?? false}
193	                  variant="ghost"
194	                />
195	              )}
196	              {onStageChange && (
197	                <Button variant="ghost" size="sm" className="h-8 gap-1.5 text-xs text-muted-foreground hover:text-destructive"
198	                  onClick={() => setRejectDialogOpen(true)}>
199	                  <UserX className="h-3 w-3" /> Reject
200	                </Button>
201	              )}
202	              <Button variant="ghost" size="sm" className="h-8 gap-1.5 text-xs text-muted-foreground hover:text-destructive"
203	                onClick={() => { onDismiss(r.resume_id); onClose(); }}>
204	                <Archive className="h-3 w-3" /> Archive
205	              </Button>
206	            </div>
207	          </div>
208	
209	          {/* Scrollable panels */}
210	          <div className="relative flex-1 min-h-0">
211	            <ScrollArea className="h-full">
212	              <div className="px-6 py-6 space-y-6">
213	                {/* 1. Stage — where is this candidate in the pipeline? */}
214	                {onStageChange && (
215	                  <StageTracker
216	                    currentStage={currentStage || "applied"}
217	                    updatedAt={stageUpdatedAt}
218	                    onStageChange={(stage) => onStageChange(r.resume_id, stage)}
219	                  />
220	                )}
221	
222	                {/* 1b. Tags + Assignee */}
223	                {(onAddTag || onRemoveTag) && (
224	                  <CandidateTagInput
225	                    resumeId={r.resume_id}
226	                    tags={tags}
227	                    onAdd={onAddTag ?? (() => {})}
228	                    onRemove={onRemoveTag ?? (() => {})}
229	                  />
230	                )}
231	                {teamMembers.length > 0 && (
232	                  <AssigneeSelector
233	                    resumeId={r.resume_id}
234	                    assignedTo={(r as any).assigned_to ?? null}
235	                    members={teamMembers}
236	                    onAssigned={(userId) => onAssigned?.(r.resume_id, userId)}
237	                  />
238	                )}
239	
240	                {/* 2. Team Notes */}
241	                {jobId && (
242	                  <CandidateNotesPanel resumeId={r.resume_id} jobId={jobId} />
243	                )}
244	
245	                {/* 2b. Scorecard summary — evaluation count + per-criterion averages */}
246	                {jobId && teamId && (
247	                  <div>
248	                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">Evaluations</p>
249	                    <ScorecardSummary resumeId={r.resume_id} jobId={jobId} teamId={teamId} />
250	                  </div>
251	                )}
252	
253	                {/* 2c. Scorecard panel — submit / update evaluation */}
254	                {jobId && teamId && (
255	                  <div>
256	                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">Your Evaluation</p>
257	                    <ScorecardPanel resumeId={r.resume_id} jobId={jobId} teamId={teamId} />
258	                  </div>
259	                )}
260	
261	                {/* 3. Rich AI Summary Card — score ring, sub-scores, must-haves, strengths, gaps, interview Qs */}
262	                <CandidateSummaryCard
263	                  result={r}
264	                  candidateName={candidateName}
265	                  compact={false}
266	                />
267	
268	                {/* 4. JD Alignment — the hiring decision: fit or not? */}
269	                <JDAlignedPanel result={r} />
270	
271	                {/* 4. Summary — AI's take on this candidate */}
272	                <CandidateSummary result={r} />
273	
274	                {/* 5. Strengths & Gaps — quick signal */}
275	                <StrengthsGapsPanel result={r} />
276	
277	                {/* 6. Skills — technical depth */}
278	                <SkillsDetailPanel result={r} />
279	
280	                {/* 7. Background — experience + education */}
281	                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
282	                  <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
283	                  <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
284	                </div>
285	
286	                {/* 8. Interviews — scheduled interviews for this candidate */}
287	                {jobId && (
288	                  <InterviewsPanel
289	                    resumeId={r.resume_id}
290	                    jobId={jobId}
291	                    candidateName={candidateName}
292	                    candidateEmail={r.candidate_email}
293	                  />
294	                )}
295	
296	                {/* 9. Authenticity analysis */}
297	                <div>
298	                  <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
299	                    Authenticity Analysis
300	                  </p>
301	                  <AuthenticityReport
302	                    resumeId={r.resume_id}
303	                    initialData={(r as any).authenticity_json ?? null}
304	                  />
305	                </div>
306	
307	                {/* 10. Interview prep — last, for next steps */}
308	                <InterviewQuestionsPanel result={r} />
309	              </div>
310	            </ScrollArea>
311	            <div className="absolute bottom-0 left-0 right-0 h-8 bg-gradient-to-t from-background to-transparent pointer-events-none" />
312	          </div>
313	        </SheetContent>
314	      </Sheet>
315	
316	      {r.candidate_email && (
317	        <EmailOutreachDialog
318	          open={emailDialogOpen}
319	          onOpenChange={setEmailDialogOpen}
320	          candidateName={candidateName}
321	          candidateEmail={r.candidate_email}
322	          jobTitle={jobTitle || "Open Position"}
323	          matchScore={Math.round(r.overall_score ?? 0)}
324	          resumeId={r.resume_id}
325	          jobId={jobId || ""}
326	        />
327	      )}
328	
329	      {jobId && (
330	        <ScheduleInterviewDialog
331	          open={scheduleOpen}
332	          onOpenChange={setScheduleOpen}
333	          jobId={jobId}
334	          resumeId={r.resume_id}
335	          candidateName={candidateName}
336	          candidateEmail={r.candidate_email}
337	        />
338	      )}
339	
340	      {jobId && (
341	        <RejectCandidateDialog
342	          open={rejectDialogOpen}
343	          onOpenChange={setRejectDialogOpen}
344	          result={r}
345	          jobTitle={jobTitle || "Open Position"}
346	          jobId={jobId}
347	          onStageChange={onStageChange}
348	        />
349	      )}
350	
351	      {r.candidate_phone && (
352	        <WhatsAppOutreachDialog
353	          open={whatsappOpen}
354	          onOpenChange={setWhatsappOpen}
355	          candidateName={candidateName}
356	          candidatePhone={r.candidate_phone}
357	          jobTitle={jobTitle || "Open Position"}
358	          matchScore={Math.round(r.overall_score ?? 0)}
359	        />
360	      )}
361	    </>
362	  );
363	};
364	
365	export default CandidateDetailSheet;
366	
