import { useState, useEffect } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent } from "@/components/ui/sheet";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import {
  Phone,
  Mail,
  Archive,
  MapPin,
  Download,
  X,
  Linkedin,
  Calendar,
  UserX,
  MessageCircle,
  MoreHorizontal,
  CheckCircle2,
  XCircle,
  Bookmark,
} from "lucide-react";
import { toast } from "sonner";
import type { Result } from "@/pages/Index";
import type { HiringStage } from "@/hooks/useStageTracker";

import CandidateSummaryCard from "@/components/candidate/CandidateSummaryCard";
import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
import ExperiencePanel from "@/components/candidate/ExperiencePanel";
import EducationPanel from "@/components/candidate/EducationPanel";
import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
import StageTracker from "@/components/candidate/StageTracker";
import ScorecardPanel from "@/components/candidate/ScorecardPanel";
import ScorecardSummary from "@/components/candidate/ScorecardSummary";
import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
import CandidateNotesPanel from "@/components/candidate/CandidateNotesPanel";
import InterviewsPanel from "@/components/candidate/InterviewsPanel";
import ScheduleInterviewDialog from "@/components/ScheduleInterviewDialog";
import RejectCandidateDialog from "@/components/candidate/RejectCandidateDialog";
import WhatsAppOutreachDialog from "@/components/candidate/WhatsAppOutreachDialog";
import CandidateTagInput from "@/components/candidate/CandidateTagInput";
import AssigneeSelector from "@/components/candidate/AssigneeSelector";
import AuthenticityReport from "@/components/candidate/AuthenticityReport";
import AddToPoolButton from "@/components/candidate/AddToPoolButton";
import { extractLinkedInUrl } from "@/lib/linkedin";
import type { CandidateTag } from "@/hooks/useCandidateTags";
import type { TeamMember } from "@/hooks/useTeam";

// ── Local sub-components ────────────────────────────────────────────────────

function ScoreRingMini({ score }: { score: number }) {
  const size = 56;
  const sw = 5;
  const r = (size - sw) / 2;
  const c = 2 * Math.PI * r;
  const v = Math.min(Math.max(score, 0), 100);
  const dash = (v / 100) * c;
  const color = v >= 70 ? "#22c55e" : v >= 40 ? "#f59e0b" : "#ef4444";
  return (
    <div
      className="relative inline-flex items-center justify-center shrink-0"
      style={{ width: size, height: size }}
    >
      <svg width={size} height={size} className="-rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={r}
          fill="none"
          stroke="currentColor"
          strokeWidth={sw}
          className="text-muted/30"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={r}
          fill="none"
          stroke={color}
          strokeWidth={sw}
          strokeDasharray={`${dash} ${c - dash}`}
          strokeLinecap="round"
        />
      </svg>
      <span
        className="absolute text-sm font-bold tabular-nums"
        style={{ color }}
      >
        {Math.round(v)}
      </span>
    </div>
  );
}

function MustHaveSkillsGrid({
  matched = [],
  missing = [],
}: {
  matched?: string[];
  missing?: string[];
}) {
  if (!matched.length && !missing.length) return null;
  return (
    <div>
      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
        Must-Have Skills
      </p>
      <div className="flex flex-wrap gap-2">
        {matched.map((s) => (
          <span
            key={s}
            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800"
          >
            <CheckCircle2 className="h-3 w-3" />
            {s}
          </span>
        ))}
        {missing.map((s) => (
          <span
            key={s}
            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-200 dark:bg-red-950/40 dark:text-red-400 dark:border-red-800"
          >
            <XCircle className="h-3 w-3" />
            {s}
          </span>
        ))}
      </div>
    </div>
  );
}

// ── Props & helpers ──────────────────────────────────────────────────────────

interface CandidateDetailSheetProps {
  result: Result | null;
  isOpen: boolean;
  onClose: () => void;
  jobId?: string | null;
  jobTitle?: string | null;
  teamId?: string | null;
  formatCandidateName: (filename: string) => string;
  onDownload: (filePath: string, filename: string) => void;
  onDismiss: (resumeId: string) => void;
  currentStage?: HiringStage | null;
  stageUpdatedAt?: string | null;
  onStageChange?: (resumeId: string, stage: HiringStage) => void;
  tags?: CandidateTag[];
  teamMembers?: TeamMember[];
  onAddTag?: (params: { resumeId: string; tag: string; color?: string }) => void;
  onRemoveTag?: (tagId: string) => void;
  onAssigned?: (resumeId: string, userId: string | null) => void;
  blindMode?: boolean;
}

const getStrengthLabel = (
  score: number
): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

// ── Main component ───────────────────────────────────────────────────────────

const CandidateDetailSheet = ({
  result: r,
  isOpen,
  onClose,
  jobId,
  jobTitle,
  teamId,
  formatCandidateName,
  onDownload,
  onDismiss,
  currentStage,
  stageUpdatedAt,
  onStageChange,
  tags = [],
  teamMembers = [],
  onAddTag,
  onRemoveTag,
  onAssigned,
  blindMode = false,
}: CandidateDetailSheetProps) => {
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
  const [scheduleOpen, setScheduleOpen] = useState(false);
  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
  const [whatsappOpen, setWhatsappOpen] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");

  // Reset tab to overview each time the sheet opens
  useEffect(() => {
    if (isOpen) setActiveTab("overview");
  }, [isOpen]);

  if (!r) return null;

  const strength = getStrengthLabel(r.overall_score);
  const linkedinUrl = extractLinkedInUrl(r);
  const candidateName = r.candidate_name || formatCandidateName(r.filename);
  const initials = candidateName
    .split(" ")
    .slice(0, 2)
    .map((n: string) => n[0])
    .join("")
    .toUpperCase();

  return (
    <>
      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
        <SheetContent
          side="right"
          className="sm:max-w-2xl w-full p-0 flex flex-col gap-0 [&>button]:hidden"
        >
          {/* ── Header ──────────────────────────────────────────────────── */}
          <div className="bg-card px-6 pt-5 pb-4 shrink-0 border-b border-border relative">
            {/* Close button */}
            <button
              onClick={onClose}
              className="absolute top-4 right-4 rounded-sm opacity-60 hover:opacity-100 transition-opacity"
            >
              <X className="h-4 w-4" />
            </button>

            {/* Identity row */}
            <div className="flex items-start gap-3 pr-6">
              {/* Avatar */}
              <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                <span className="text-sm font-semibold text-primary">{initials}</span>
              </div>

              {/* Name + meta */}
              <div className="flex-1 min-w-0">
                <h2 className="text-lg font-semibold text-foreground truncate">
                  {blindMode ? "Candidate" : candidateName}
                </h2>
                <div className="flex items-center gap-3 mt-0.5 flex-wrap">
                  {r.candidate_location && (
                    <span className="flex items-center gap-1 text-xs text-muted-foreground">
                      <MapPin className="h-3 w-3" />
                      {r.candidate_location}
                    </span>
                  )}
                  {r.candidate_email && (
                    <span className="text-xs text-muted-foreground truncate">
                      {r.candidate_email}
                    </span>
                  )}
                </div>
              </div>

              {/* Score ring */}
              <ScoreRingMini score={r.overall_score ?? 0} />
            </div>

            {/* Badge + confidence row */}
            <div className="flex items-center gap-2 mt-3 flex-wrap">
              <Badge variant={strength.variant}>{strength.label}</Badge>
              {r.scoring_version === "heuristic" && (
                <Badge variant="secondary">Quick</Badge>
              )}
              {r.confidence != null && (
                <Badge variant="outline" className="text-muted-foreground">
                  {r.confidence}% confidence
                </Badge>
              )}
            </div>

            {/* Action row */}
            <div className="flex items-center gap-1 mt-3 flex-wrap">
              <TooltipProvider>
                {r.candidate_phone && (
                  <>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button
                          variant="outline"
                          size="icon"
                          className="h-8 w-8"
                          onClick={() => {
                            navigator.clipboard.writeText(r.candidate_phone!);
                            toast.success("Phone copied!");
                          }}
                        >
                          <Phone className="h-4 w-4" />
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>Copy phone</TooltipContent>
                    </Tooltip>

                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button
                          variant="outline"
                          size="icon"
                          className="h-8 w-8 border-[#25D366]/30 text-[#25D366] hover:bg-[#25D366]/10"
                          onClick={() => setWhatsappOpen(true)}
                        >
                          <MessageCircle className="h-4 w-4" />
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>WhatsApp</TooltipContent>
                    </Tooltip>
                  </>
                )}

                {r.candidate_email && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        variant="outline"
                        size="icon"
                        className="h-8 w-8"
                        onClick={() => setEmailDialogOpen(true)}
                      >
                        <Mail className="h-4 w-4" />
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Send email</TooltipContent>
                  </Tooltip>
                )}

                {jobId && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        variant="outline"
                        size="icon"
                        className="h-8 w-8"
                        onClick={() => setScheduleOpen(true)}
                      >
                        <Calendar className="h-4 w-4" />
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Schedule interview</TooltipContent>
                  </Tooltip>
                )}
              </TooltipProvider>

              {/* Stage tracker — right-aligned */}
              {onStageChange && (
                <div className="ml-auto">
                  <StageTracker
                    currentStage={currentStage || "applied"}
                    updatedAt={stageUpdatedAt}
                    onStageChange={(stage) => onStageChange(r.resume_id, stage)}
                  />
                </div>
              )}

              {/* Overflow dropdown */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size="icon" className="h-8 w-8 shrink-0">
                    <MoreHorizontal className="h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-44">
                  {r.file_path && (
                    <DropdownMenuItem
                      onClick={() => onDownload(r.file_path!, r.filename)}
                    >
                      <Download className="h-3.5 w-3.5 mr-2" />
                      Download resume
                    </DropdownMenuItem>
                  )}
                  {linkedinUrl && (
                    <DropdownMenuItem
                      onClick={() =>
                        window.open(linkedinUrl, "_blank", "noopener,noreferrer")
                      }
                    >
                      <Linkedin className="h-3.5 w-3.5 mr-2" />
                      LinkedIn profile
                    </DropdownMenuItem>
                  )}
                  {jobId && teamId && (
                    <DropdownMenuItem asChild>
                      <div className="flex items-center">
                        <Bookmark className="h-3.5 w-3.5 mr-2" />
                        <AddToPoolButton
                          resumeId={r.resume_id}
                          jobId={jobId}
                          teamId={teamId}
                          isInPool={(r as any).in_talent_pool ?? false}
                          variant="ghost"
                        />
                      </div>
                    </DropdownMenuItem>
                  )}
                  <DropdownMenuSeparator />
                  {onStageChange && (
                    <DropdownMenuItem
                      className="text-destructive focus:text-destructive"
                      onClick={() => setRejectDialogOpen(true)}
                    >
                      <UserX className="h-3.5 w-3.5 mr-2" />
                      Reject
                    </DropdownMenuItem>
                  )}
                  <DropdownMenuItem
                    className="text-destructive focus:text-destructive"
                    onClick={() => { onDismiss(r.resume_id); onClose(); }}
                  >
                    <Archive className="h-3.5 w-3.5 mr-2" />
                    Archive
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>

          {/* ── Tabs ────────────────────────────────────────────────────── */}
          <Tabs
            value={activeTab}
            onValueChange={setActiveTab}
            className="flex flex-col flex-1 min-h-0"
          >
            <TabsList className="px-6 h-10 border-b border-border bg-transparent rounded-none justify-start gap-0 shrink-0">
              {["overview", "analysis", "team", "history"].map((tab) => (
                <TabsTrigger
                  key={tab}
                  value={tab}
                  className="text-sm rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:text-foreground data-[state=active]:shadow-none text-muted-foreground px-3 h-10 capitalize"
                >
                  {tab}
                </TabsTrigger>
              ))}
            </TabsList>

            {/* ── Overview tab ──────────────────────────────────────────── */}
            <TabsContent value="overview" className="flex-1 min-h-0 mt-0">
              <ScrollArea className="h-full">
                <div className="px-6 py-6 space-y-6">
                  <MustHaveSkillsGrid
                    matched={r.matched_must_haves as string[] | undefined}
                    missing={r.missing_must_haves as string[] | undefined}
                  />
                  <StrengthsGapsPanel result={r} />
                  <InterviewQuestionsPanel result={r} />
                  {(onAddTag || onRemoveTag) && (
                    <CandidateTagInput
                      resumeId={r.resume_id}
                      tags={tags}
                      onAdd={onAddTag ?? (() => {})}
                      onRemove={onRemoveTag ?? (() => {})}
                    />
                  )}
                </div>
              </ScrollArea>
            </TabsContent>

            {/* ── Analysis tab ──────────────────────────────────────────── */}
            <TabsContent value="analysis" className="flex-1 min-h-0 mt-0">
              <ScrollArea className="h-full">
                <div className="px-6 py-6 space-y-6">
                  <CandidateSummaryCard
                    result={r}
                    candidateName={candidateName}
                    compact={false}
                  />
                  <JDAlignedPanel result={r} />
                  <SkillsDetailPanel result={r} />
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <ExperiencePanel
                      parsedJson={r.parsed_json}
                      matchedMustHaves={r.matched_must_haves as string[]}
                    />
                    <EducationPanel
                      parsedJson={r.parsed_json}
                      matchedMustHaves={r.matched_must_haves}
                      missingMustHaves={r.missing_must_haves}
                    />
                  </div>
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
                      Authenticity Analysis
                    </p>
                    <AuthenticityReport
                      resumeId={r.resume_id}
                      initialData={(r as any).authenticity_json ?? null}
                    />
                  </div>
                </div>
              </ScrollArea>
            </TabsContent>

            {/* ── Team tab ──────────────────────────────────────────────── */}
            <TabsContent value="team" className="flex-1 min-h-0 mt-0">
              <ScrollArea className="h-full">
                <div className="px-6 py-6 space-y-6">
                  {teamMembers.length > 0 && (
                    <AssigneeSelector
                      resumeId={r.resume_id}
                      assignedTo={(r as any).assigned_to ?? null}
                      members={teamMembers}
                      onAssigned={(userId) => onAssigned?.(r.resume_id, userId)}
                    />
                  )}
                  {jobId && (
                    <CandidateNotesPanel resumeId={r.resume_id} jobId={jobId} />
                  )}
                  {jobId && teamId && (
                    <div>
                      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
                        Evaluations
                      </p>
                      <ScorecardSummary
                        resumeId={r.resume_id}
                        jobId={jobId}
                        teamId={teamId}
                      />
                    </div>
                  )}
                  {jobId && teamId && (
                    <div>
                      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
                        Your Evaluation
                      </p>
                      <ScorecardPanel
                        resumeId={r.resume_id}
                        jobId={jobId}
                        teamId={teamId}
                      />
                    </div>
                  )}
                </div>
              </ScrollArea>
            </TabsContent>

            {/* ── History tab ───────────────────────────────────────────── */}
            <TabsContent value="history" className="flex-1 min-h-0 mt-0">
              <ScrollArea className="h-full">
                <div className="px-6 py-6 space-y-6">
                  {jobId && (
                    <InterviewsPanel
                      resumeId={r.resume_id}
                      jobId={jobId}
                      candidateName={candidateName}
                      candidateEmail={r.candidate_email}
                    />
                  )}
                </div>
              </ScrollArea>
            </TabsContent>
          </Tabs>
        </SheetContent>
      </Sheet>

      {/* ── Dialogs (outside Sheet to avoid stacking context issues) ──────── */}
      {r.candidate_email && (
        <EmailOutreachDialog
          open={emailDialogOpen}
          onOpenChange={setEmailDialogOpen}
          candidateName={candidateName}
          candidateEmail={r.candidate_email}
          jobTitle={jobTitle || "Open Position"}
          matchScore={Math.round(r.overall_score ?? 0)}
          resumeId={r.resume_id}
          jobId={jobId || ""}
        />
      )}

      {jobId && (
        <ScheduleInterviewDialog
          open={scheduleOpen}
          onOpenChange={setScheduleOpen}
          jobId={jobId}
          resumeId={r.resume_id}
          candidateName={candidateName}
          candidateEmail={r.candidate_email}
        />
      )}

      {jobId && (
        <RejectCandidateDialog
          open={rejectDialogOpen}
          onOpenChange={setRejectDialogOpen}
          result={r}
          jobTitle={jobTitle || "Open Position"}
          jobId={jobId}
          onStageChange={onStageChange}
        />
      )}

      {r.candidate_phone && (
        <WhatsAppOutreachDialog
          open={whatsappOpen}
          onOpenChange={setWhatsappOpen}
          candidateName={candidateName}
          candidatePhone={r.candidate_phone}
          jobTitle={jobTitle || "Open Position"}
          matchScore={Math.round(r.overall_score ?? 0)}
        />
      )}
    </>
  );
};

export default CandidateDetailSheet;
